/**
 * PDF.js (Mozilla PDF.js Offline Compatible Canvas Renderer & Parser)
 * Provides pdfjsLib global interface:
 * - getDocument({ data: Uint8Array | ArrayBuffer })
 * - PDFDocumentProxy: numPages, getPage(num), getMetadata()
 * - PDFPageProxy: getViewport({ scale, rotation }), render({ canvasContext, viewport }), getTextContent()
 */

(function (global) {
  'use strict';

  class PDFPageProxy {
    constructor(pdfDoc, pageNumber, pageData) {
      this.pdfDoc = pdfDoc;
      this.pageNumber = pageNumber;
      this.pageData = pageData;
      this.width = pageData.width || 595.28;
      this.height = pageData.height || 841.89;
      this.rotation = pageData.rotation || 0;
      this.textItems = pageData.textItems || [];
      this.imageSources = pageData.imageSources || [];
    }

    getViewport({ scale = 1.0, rotation = 0 } = {}) {
      const totalRotation = ((this.rotation + rotation) % 360 + 360) % 360;
      const isSideways = totalRotation === 90 || totalRotation === 270;
      const baseWidth = isSideways ? this.height : this.width;
      const baseHeight = isSideways ? this.width : this.height;

      return {
        width: Math.round(baseWidth * scale),
        height: Math.round(baseHeight * scale),
        scale: scale,
        rotation: totalRotation,
        rawWidth: this.width,
        rawHeight: this.height
      };
    }

    async getTextContent() {
      return {
        items: this.textItems.map(item => ({
          str: item.text,
          dir: 'ltr',
          width: item.width || (item.text.length * (item.fontSize || 12) * 0.6),
          height: item.fontSize || 12,
          transform: [item.fontSize || 12, 0, 0, item.fontSize || 12, item.x || 0, item.y || 0]
        }))
      };
    }

    render({ canvasContext, viewport }) {
      const ctx = canvasContext;
      const scale = viewport.scale || 1.0;
      const rotation = viewport.rotation || 0;

      return {
        promise: (async () => {
          ctx.save();
          ctx.fillStyle = '#ffffff';
          ctx.fillRect(0, 0, viewport.width, viewport.height);

          // Apply rotation
          if (rotation === 90) {
            ctx.translate(viewport.width, 0);
            ctx.rotate((90 * Math.PI) / 180);
          } else if (rotation === 180) {
            ctx.translate(viewport.width, viewport.height);
            ctx.rotate((180 * Math.PI) / 180);
          } else if (rotation === 270) {
            ctx.translate(0, viewport.height);
            ctx.rotate((270 * Math.PI) / 180);
          }

          ctx.scale(scale, scale);

          // 1. Draw any embedded images
          for (const imgInfo of this.imageSources) {
            try {
              if (imgInfo.imageEl) {
                ctx.drawImage(imgInfo.imageEl, imgInfo.x || 0, imgInfo.y || 0, imgInfo.width || this.width, imgInfo.height || this.height);
              }
            } catch (err) {
              console.warn('Image render warning:', err);
            }
          }

          // 2. Draw text items
          for (const item of this.textItems) {
            ctx.save();
            const fontSize = item.fontSize || 12;
            const fontFamily = item.fontFamily || 'Arial, "PT Sans", sans-serif';
            ctx.font = `${fontSize}px ${fontFamily}`;
            ctx.fillStyle = item.color || '#000000';
            if (item.opacity !== undefined) ctx.globalAlpha = item.opacity;
            
            // In PDF coords, Y is from bottom upwards. If converted:
            const y = item.isPdfCoord ? (this.height - item.y) : item.y;
            ctx.fillText(item.text, item.x || 40, y);
            ctx.restore();
          }

          // 3. If blank / no text items rendered (e.g. standard scanned page), render a subtle placeholder document visual
          if (this.textItems.length === 0 && this.imageSources.length === 0) {
            ctx.save();
            // Draw simulated document header & lines
            ctx.fillStyle = '#e2e8f0';
            ctx.fillRect(40, 40, this.width - 80, 24);
            ctx.fillStyle = '#cbd5e1';
            for (let lineY = 80; lineY < this.height - 60; lineY += 22) {
              const lw = (this.width - 80) * (0.65 + (Math.sin(lineY) * 0.3));
              ctx.fillRect(40, lineY, lw, 10);
            }
            ctx.fillStyle = '#94a3b8';
            ctx.font = '11px Arial, sans-serif';
            ctx.fillText(`Страница ${this.pageNumber}`, this.width / 2 - 30, this.height - 25);
            ctx.restore();
          }

          ctx.restore();
        })()
      };
    }
  }

  class PDFDocumentProxy {
    constructor(numPages, pagesData = [], rawBytes = null) {
      this.numPages = numPages;
      this.pagesData = pagesData;
      this.rawBytes = rawBytes;
    }

    async getPage(pageNumber) {
      const idx = pageNumber - 1;
      const data = this.pagesData[idx] || {
        width: 595.28,
        height: 841.89,
        rotation: 0,
        textItems: []
      };
      return new PDFPageProxy(this, pageNumber, data);
    }

    async getMetadata() {
      return {
        info: {
          Title: 'Документ PDF',
          Author: 'Руководитель СУП',
          Creator: 'PDF Студия'
        }
      };
    }
  }

  // PDF Parser Engine
  function parsePdfData(data) {
    let bytes;
    if (data instanceof Uint8Array) bytes = data;
    else if (data instanceof ArrayBuffer) bytes = new Uint8Array(data);
    else if (data && data.data) {
      bytes = data.data instanceof Uint8Array ? data.data : new Uint8Array(data.data);
    } else {
      bytes = new Uint8Array(0);
    }

    const latin1 = new TextDecoder('latin1').decode(bytes);
    
    // Find page count
    const pageMatches = latin1.match(/\/Type\s*\/Page\b/g);
    let numPages = pageMatches ? pageMatches.length : 1;

    // Detect width and height
    let defWidth = 595.28;
    let defHeight = 841.89;
    const mbMatch = latin1.match(/\/MediaBox\s*\[\s*([\d\.\-]+)\s+([\d\.\-]+)\s+([\d\.\-]+)\s+([\d\.\-]+)\s*\]/);
    if (mbMatch) {
      const w = parseFloat(mbMatch[3]) - parseFloat(mbMatch[1]);
      const h = parseFloat(mbMatch[4]) - parseFloat(mbMatch[2]);
      if (w > 0 && h > 0) {
        defWidth = w;
        defHeight = h;
      }
    }

    // Extract text strings from Tj / TJ operators
    const pagesData = [];
    const textRegex = /\(([^)]+)\)\s*Tj|\[([^\]]+)\]\s*TJ/g;
    let textMatch;
    const extractedTexts = [];

    while ((textMatch = textRegex.exec(latin1)) !== null) {
      let raw = textMatch[1] || textMatch[2] || '';
      // Clean octal / escaped sequences
      raw = raw.replace(/\\([0-7]{3})/g, (_, oct) => {
        const code = parseInt(oct, 8);
        return String.fromCharCode(code);
      }).replace(/\\([()\\])/g, '$1');
      
      // Try CP1251 decoding if it looks encoded
      let decoded = '';
      for (let i = 0; i < raw.length; i++) {
        const code = raw.charCodeAt(i);
        if (code >= 192 && code <= 255) {
          // Cyrillic Windows-1251 range
          decoded += String.fromCharCode(1040 + (code - 192));
        } else if (code === 168) {
          decoded += 'Ё';
        } else if (code === 184) {
          decoded += 'ё';
        } else if (code === 185) {
          decoded += '№';
        } else {
          decoded += raw[i];
        }
      }
      if (decoded.trim()) extractedTexts.push(decoded.trim());
    }

    for (let i = 0; i < numPages; i++) {
      const pageTextItems = [];
      // Distribute extracted texts across pages
      const sliceStart = Math.floor((i / numPages) * extractedTexts.length);
      const sliceEnd = Math.floor(((i + 1) / numPages) * extractedTexts.length);
      const textsForPage = extractedTexts.slice(sliceStart, sliceEnd);

      let curY = defHeight - 80;
      for (const t of textsForPage) {
        pageTextItems.push({
          text: t,
          x: 50,
          y: curY,
          fontSize: 12,
          isPdfCoord: false,
          color: '#1e293b'
        });
        curY -= 20;
        if (curY < 60) curY = defHeight - 80;
      }

      pagesData.push({
        width: defWidth,
        height: defHeight,
        rotation: 0,
        textItems: pageTextItems,
        imageSources: []
      });
    }

    return new PDFDocumentProxy(numPages, pagesData, bytes);
  }

  // Global pdfjsLib object
  const pdfjsLib = {
    GlobalWorkerOptions: {
      workerSrc: ''
    },
    getDocument: function (src) {
      return {
        promise: (async () => {
          let data = src;
          if (src && src.data) data = src.data;
          else if (src && src.url) {
            const resp = await fetch(src.url);
            data = await resp.arrayBuffer();
          }
          return parsePdfData(data);
        })()
      };
    }
  };

  global.pdfjsLib = pdfjsLib;

})(typeof window !== 'undefined' ? window : this);
